    static unsigned GetElementBitWidth(VectorElemKind elem) {
        switch (elem) {
        case VectorElemKind::I32:
        case VectorElemKind::F32:
            return 32;
        case VectorElemKind::FP8:
            return 8;
        case VectorElemKind::F16:
        case VectorElemKind::BF16:
            return 16;
        }
        return 0;
